1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // projects references clients (FK); H2 refuses to TRUNCATE an FK-referenced table, so lift
36	        // referential integrity for the duration of the reset.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        try {
39	            jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
40	            jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
41	            jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
42	            jdbc.execute("TRUNCATE TABLE line_items RESTART IDENTITY");
43	            jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
44	            jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
45	            jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
46	            jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
47	        } finally {
48	            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
49	        }
50	    }
51	
52	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
53	    @SuppressWarnings("unchecked")
54	    @PostMapping("/seed")
55	    public void seed(@RequestBody Map<String, Object> fixture) {
56	        List<Map<String, Object>> clients =
57	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
58	        for (Map<String, Object> c : clients) {
59	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
60	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
61	        }
62	        List<Map<String, Object>> projects =
63	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
64	        for (Map<String, Object> p : projects) {
65	            jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
66	                    ((Number) p.get("id")).longValue(), p.get("name"),
67	                    ((Number) p.get("clientId")).longValue());
68	        }
69	        List<Map<String, Object>> contacts =
70	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
71	        for (Map<String, Object> ct : contacts) {
72	            jdbc.update(
73	                    "INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
74	                    ((Number) ct.get("id")).longValue(),
75	                    ((Number) ct.get("clientId")).longValue(),
76	                    ct.get("name"), ct.get("email"), ct.get("role"));
77	        }
78	        List<Map<String, Object>> tasks =
79	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
80	        for (Map<String, Object> t : tasks) {
81	            Object done = t.get("done");
82	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
83	                    ((Number) t.get("id")).longValue(),
84	                    ((Number) t.get("projectId")).longValue(),
85	                    t.get("title"),
86	                    done != null && Boolean.parseBoolean(done.toString()));
87	        }
88	        List<Map<String, Object>> tags =
89	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
90	        for (Map<String, Object> tg : tags) {
91	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)",
92	                    ((Number) tg.get("id")).longValue(), tg.get("name"));
93	        }
94	        List<Map<String, Object>> projectTags =
95	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
96	        for (Map<String, Object> pt : projectTags) {
97	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
98	                    ((Number) pt.get("projectId")).longValue(),
99	                    ((Number) pt.get("tagId")).longValue());
100	        }
101	        List<Map<String, Object>> invoices =
102	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
103	        for (Map<String, Object> inv : invoices) {
104	            Object status = inv.get("status");
105	            Object issuedDate = inv.get("issuedDate");
106	            Object dueDate = inv.get("dueDate");
107	            // Amount is derived from the invoice's line items (V13), so it is not seeded directly;
108	            // the column defaults to 0.
109	            jdbc.update(
110	                    "INSERT INTO invoices (id, project_id, status, issued_date, due_date)"
111	                            + " VALUES (?, ?, ?, ?, ?)",
112	                    ((Number) inv.get("id")).longValue(),
113	                    ((Number) inv.get("projectId")).longValue(),
114	                    status == null ? "DRAFT" : status.toString(),
115	                    issuedDate == null ? null : java.sql.Date.valueOf(issuedDate.toString()),
116	                    dueDate == null ? null : java.sql.Date.valueOf(dueDate.toString()));
117	            List<Map<String, Object>> lineItems =
118	                    (List<Map<String, Object>>) inv.getOrDefault("lineItems", List.of());
119	            for (Map<String, Object> li : lineItems) {
120	                jdbc.update(
121	                        "INSERT INTO line_items (id, invoice_id, description, qty, unit_price)"
122	                                + " VALUES (?, ?, ?, ?, ?)",
123	                        ((Number) li.get("id")).longValue(),
124	                        ((Number) inv.get("id")).longValue(),
125	                        li.get("description"),
126	                        ((Number) li.get("qty")).intValue(),
127	                        new java.math.BigDecimal(li.get("unitPrice").toString()));
128	            }
129	        }
130	    }
131	}
